def transform(grid):
    if not grid:
        return []

    r, c = len(grid), len(grid[0])

    # Try main diagonals (r-c) first, then anti-diagonals (r+c)
    for key in [lambda x: x[0]-x[1], lambda x: x[0]+x[1]]:
        diag_values = {}
        conflicts = False

        for i in range(r):
            for j in range(c):
                if grid[i][j] != 0:
                    k = key((i, j))
                    if k not in diag_values or diag_values[k] != grid[i][j]:
                        conflicts = True
                        break
                    diag_values[k] = grid[i][j]
            if conflicts:
                break

        if not conflicts and diag_values:
            # Valid grouping found
            unique_keys = list(diag_values.keys())
            L = len(unique_keys)

            # Check if mapping is consistent (mod L)
            value_map = {}
            for k, v in diag_values.items():
                rem = k % L
                if rem in value_map and value_map[rem] != v:
                    # Conflict with modular consistency, try other direction
                    break
                value_map[rem] = v
            else:
                # No conflicts found, use this direction
                output = [[0]*c for _ in range(r)]
                for i in range(r):
                    for j in range(c):
                        k = key((i, j))
                        val = value_map.get(k % L, 0)
                        output[i][j] = val
                return output
